Script:
CompanyImportCSVLinesView = {
    init: async function(app, container, company) {
        app = app || session.app;
        container = container || $(".component[name=CompanyImportCSVLinesView]");

        this.buildLinesGrid({
            element: $("[name=company-csv-line-detail]", container),
            data: company
        }, container).init();
    },

    buildLinesGrid: function(variables) {
        var g = new ReadOnlyDetailView(variables.element);
        g.data = variables.data;
        g.title = "Import Line Details";
        g.fields = [
            {
                field: "Id",
                title: "[resource_shortdisplayname[Id]]",
                description: "[resource_description[Id]]"
            },
            {
                field: "RootBucketId",
                title: "[resource_shortdisplayname[RootBucketId]]",
                description: "[resource_description[RootBucketId]]"
            },
            {
                field: "CompanyId",
                template: function (data) { return "" + ((data.CompanyId) ? ('<a href="/B2B/Company/' + '?Id=' + data.CompanyId + '">' + data.CompanyId + '</a>') : '') + ""; },
                title: "[resource_shortdisplayname[CompanyId]]",
                description: "[resource_description[CompanyId]]"
            },
            {
                field: "Perspective",
                title: "[resource_shortdisplayname[Perspective]]",
                description: "[resource_description[Perspective]]"
            },
            {
                field: "SourceSystemId",
                title: "[resource_shortdisplayname[SourceSystemId]]",
                description: "[resource_description[SourceSystemId]]"
            },
            {
                field: "ReferenceSeperator",
                title: "[resource_shortdisplayname[ReferenceSeperator]]",
                description: "[resource_description[ReferenceSeperator]]"
            },
            {
                field: "FileName",
                title: "[resource_shortdisplayname[FileName]]",
                description: "[resource_description[FileName]]"
            },
            {
                field: "Name",
                title: "[resource_shortdisplayname[Name]]",
                description: "[resource_description[Name]]"
            },
            {
                field: "FailureMessage",
                title: "[resource_shortdisplayname[FailureMessage]]",
                description: "[resource_description[FailureMessage]]"
            },
            {
                field: "CreatedBy",
                title: "[resource_shortdisplayname[CreatedBy]]",
                description: "[resource_description[CreatedBy]]"
            },
            {
                field: "Reference",
                title: "[resource_shortdisplayname[Reference]]",
                description: "[resource_description[Reference]]"
            },
            {
                field: "GlobalTax",
                title: "[resource_shortdisplayname[GlobalTax]]",
                description: "[resource_description[GlobalTax]]"
            },
            {
                field: "AddressLine1",
                title: "[resource_shortdisplayname[AddressLine1]]",
                description: "[resource_description[AddressLine1]]"
            },
            {
                field: "AddressLine2",
                title: "[resource_shortdisplayname[AddressLine2]]",
                description: "[resource_description[AddressLine2]]"
            },
            {
                field: "AddressZipOrPostalCode",
                title: "[resource_shortdisplayname[AddressZipOrPostalCode]]",
                description: "[resource_description[AddressZipOrPostalCode]]"
            },
            {
                field: "AddressTownOrCity",
                title: "[resource_shortdisplayname[AddressTownOrCity]]",
                description: "[resource_description[AddressTownOrCity]]"
            },
            {
                field: "AddressPoBox",
                title: "[resource_shortdisplayname[AddressPoBox]]",
                description: "[resource_description[AddressPoBox]]"
            },
            {
                field: "AddressRegion",
                title: "[resource_shortdisplayname[AddressRegion]]",
                description: "[resource_description[AddressRegion]]"
            },
            {
                field: "AddressCountryId",
                title: "[resource_shortdisplayname[AddressCountryId]]",
                description: "[resource_description[AddressCountryId]]"
            },
            {
                field: "ProcessingState",
                title: "[resource_shortdisplayname[ProcessingState]]",
                description: "[resource_description[ProcessingState]]"
            },
            {
                field: "CreatedOn",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[CreatedOn]]",
                description: "[resource_description[CreatedOn]]"
            },
            {
                field: "ProcessedOn",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[ProcessedOn]]",
                description: "[resource_description[ProcessedOn]]"
            }
        ];
        g.splits = ['CreatedBy', 'AddressTownOrCity'];
        return g;
    }
};
